import{_ as i,o as e,c as n,aw as o}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Особенности","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-function/function/info.md","filePath":"wiki/dev-commit/js/js-function/function/info.md"}'),a={name:"wiki/dev-commit/js/js-function/function/info.md"};function s(r,t,l,c,u,f){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="особенности" tabindex="-1">Особенности <a class="header-anchor" href="#особенности" aria-label="Permalink to &quot;Особенности&quot;">​</a></h1><ul><li><strong>Аргумент функции</strong> - передаваемое значение</li><li><strong>Параметр функции</strong> - принимаемое значение</li><li>Директива return может использоваться без значения, чтобы прекратить выполнение и выйти из функции</li><li>Если в функции не указан return, она вернет undefined</li><li>Функции (Function Declaration) совершают поднятие hoisting к началу контекста в котором объявлены, поэтому можно использовать функции до их объявления</li><li>Функция - это особый тип объекта со специальными свойствами, например, constructor и call</li></ul><h3 id="функции-объекты-первого-класса-first-class-objects" tabindex="-1">Функции - объекты первого класса (First-class Objects) <a class="header-anchor" href="#функции-объекты-первого-класса-first-class-objects" aria-label="Permalink to &quot;Функции - объекты первого класса (First-class Objects)&quot;">​</a></h3><ul><li>Функции называют объектами первого класса, потому что они обрабатываются также, как и любое другое значение в JS. Они могут присваиваться переменным, быть свойством объекта (методом), элементом массива, аргументом другой функции, значением, возвращаемым функцией. Единственным отличием функции от любого другого значения в JS является то, что функция может быть выполнена или вызвана</li></ul>',4)])])}const m=i(a,[["render",s]]);export{_ as __pageData,m as default};
